function runEndPopup(){let clear=lastResult?.clear;return popup(clear?'CHAPTER CLEAR!':'JOURNEY OVER',clear?'gold':'grey',`<div class="g-event-art">${clear?icon.boss:icon.skull}</div><div class="g-chips"><div class="g-chip">${icon.star}<span>${chapterStars(run().chapter)}<small>chapter stars</small></span></div><div class="g-chip">${icon.gold}<span>+${run().earned}<small>gold earned</small></span></div></div>${btn('end-home','HOME','big green')}`,clear?'<div class="g-rays"></div>':'');}
