 let items=offers.map((id,i)=>`<button class="g-buff" data-action="buy" data-id="${id}" ${r.coins<R[id].shopPrice?'disabled':''} style="animation-delay:${i*.1}s">${buffIcon(id)}<div><strong>${R[id].name}</strong><p>${R[id].desc}</p></div><span class="price">${icon.coin}${R[id].shopPrice}</span></button>`).join('');
