function renderBattle(){if(!pool)return;stage.renderer.setClearColor(0x000000,0);document.querySelector<HTMLElement>('#app')!.dataset.screen='battle';place('0','calc(100% - 180px - env(safe-area-inset-bottom, 0px))',true);labels.style.display='block';stage.resize();
 let two=pool.paths.length>1,bossBar=battle?`<div class="g-boss"><div class="row">${icon.boss}<span class="g-o">${currentMap.name}</span><span class="rage g-o" id="g-rage" style="display:none"></span></div><div class="g-bar red"><i id="g-bosshp"></i></div></div>`:`<div class="g-inkmeter" id="g-ink">${icon.ink}<div class="g-bar blue"><i id="g-inkfill"></i></div><b class="g-o" id="g-inknum"></b></div>${pool.goldBudget?`<div class="g-res g-gink">${icon.goldInk}<b id="g-goldnum">${Math.floor(pool.gold)}</b></div>`:''}`;
 let teamPick=two&&!battle?`<div class="g-teampick">${pool.paths.map((p,i)=>`<button class="g-tp team-${i}" data-action="team" data-team="${i}">${'AB'[i]}</button>`).join('')}</div>`:'';
 let campsHud=currentMap.camps.length?`<div class="g-campstars" id="g-camps">${stars(battle?battle.campsDestroyed:0,currentMap.camps.length)}</div>`:'';
 const brushBadge=`<button class="battle-brush" data-action="inspect-active-brush" aria-label="Inspect ${BR[run().brush].name}"><img src="${brushImage(run().brush)}" alt=""><span><small>YOUR BRUSH</small><b>${BR[run().brush].name}</b></span></button>`;let bottom=battle?`<div class="battle-loadout ${two?'two-front':''}">${brushBadge}<div class="g-avatars" id="g-avatars">${avatars()}</div></div><div class="g-actions">${btn('speed',`×${speed}`,'blue g-speed')}<span class="g-sub" id="g-time" style="flex:1">Auto battle</span></div>`:`<div class="battle-loadout ${two?'two-front':''}">${brushBadge}<div class="g-avatars">${avatars()}</div></div><div class="g-actions">${btn('undo',icon.undo,'g-round')}${btn('reset',icon.reset,'g-round')}${btn('start','MARCH!','big shine',!pool.valid)}</div>`;let forecastBox=battle?'':'<div class="g-forecast" id="g-forecast" hidden></div>';
 ui.innerHTML=`<header class="g-hud">${btn('pause',icon.pause,'g-round')}${bossBar}</header><div class="g-stagepill">${stageTag()} · ${currentMap.name}<small>${icon.boss} Defeat the boss to win${currentMap.camps.length?` · ${icon.star} camps = stars`:''}</small></div>${campsHud}${teamPick}${battle?'':'<div class="g-hint" id="g-hint"></div>'}${forecastBox}<footer class="g-bottom">${bottom}</footer>${preparing&&!battle?preparePopup():''}${brushInspect?activeBrushPopup():''}`;addDebug();if(battle)updateBattleHud();else updateInk();coach();}
function updateInk(){if(!pool)return;let ink=Math.max(0,pool.ink),fill=ui.querySelector<HTMLElement>('#g-inkfill'),num=ui.querySelector('#g-inknum'),meter=ui.querySelector('#g-ink'),gold=ui.querySelector('#g-goldnum');if(fill)fill.style.width=Math.min(100,ink/currentMap.baseInk*100)+'%';if(num)num.innerHTML=`${Math.floor(ink)}<small>+${Math.floor(ink*C.inkToXp*(1+runValue(run(),'rb_frugal')))} XP</small>`;meter?.classList.toggle('low',ink<currentMap.baseInk*.15);if(gold)gold.textContent=String(Math.floor(pool.gold));
 let path=pool.paths[active],start=ui.querySelector<HTMLButtonElement>('[data-action=start]');if(start)start.disabled=!pool.valid;for(const a of ['undo','reset']){let b=ui.querySelector<HTMLButtonElement>(`[data-action=${a}]`);if(b)b.disabled=!path.points.length;}
 ui.querySelectorAll<HTMLElement>('.g-tp').forEach((b,i)=>{b.classList.toggle('on',i===active);b.classList.toggle('ok',pool!.paths[i].valid);b.textContent='AB'[i]+(pool!.paths[i].valid?' ✓':'');});
 let hint=ui.querySelector<HTMLElement>('#g-hint');if(hint){let err=pool.error,two=pool.paths.length>1,next=pool.paths.findIndex(p=>!p.valid),text=err?err:pool.valid?'':grace?'Touch the tip to keep drawing!':two&&path.valid&&next>=0?`Now draw squad ${'AB'[next]}`:!path.points.length?(two?`Drag from flag ${'AB'[active]} to a boss`:'Draw from START to the boss. Camps earn stars.'):'';hint.textContent=text;hint.className='g-hint '+(err?'err':pool.valid?'ok':'');hint.style.display=text&&!drawing?'':'none';const lesson=ui.querySelector<HTMLElement>('.tut-passive');if(lesson)lesson.style.display=err||grace||drawing?'none':'';hint.style.visibility=err||grace?'':lesson?'hidden':'';}
 stage.ribbon(pool);queueForecast();if(pool.valid!==lastValid){lastValid=pool.valid;if(lastValid){const goal=pool.paths[active].points.at(-1)!;stage.juice.burst(goal.x,stage.elevation(goal)+12,goal.y,'loot');stage.sound.play('heal');}coach();}}
let lastValid=false,forecastTimer=0,forecastKey='';
// Mô phỏng nhanh trận đánh ngay khi đường hợp lệ để báo trước thắng/thua
function queueForecast(){clearTimeout(forecastTimer);const box=ui.querySelector<HTMLElement>('#g-forecast');if(!box||!pool)return;if(!pool.valid){box.hidden=true;forecastKey='';return;}const key=pool.paths.map(p=>p.points.length+':'+Math.round(p.spent)).join('|')+run().brush;if(key===forecastKey&&!box.hidden)return;forecastKey=key;box.hidden=false;box.className='g-forecast wait';box.innerHTML='<b>Forecast…</b>';const myKey=key;forecastTimer=window.setTimeout(()=>{if(!pool?.valid)return;const b=new Battle(currentMap,pool,run(),save,false);const slice=()=>{if(forecastKey!==myKey||screen!=='battle'||battle)return;const t0=performance.now();while(!b.result&&b.time<=C.battleTimeoutSec+1&&performance.now()-t0<10)b.step(1/60);if(!b.result&&b.time<=C.battleTimeoutSec+1){requestAnimationFrame(slice);return;}done(b);};slice();},250);
 const done=(b:Battle)=>{const alive=b.soldiers.filter(s=>s.team===0&&s.hp>0).length,total=b.soldiers.filter(s=>s.team===0).length,win=b.result==='win',close=win&&alive<total*.35,starsN=win?Math.min(3,b.campsDestroyed+Math.max(0,3-currentMap.camps.length)):0;box.className='g-forecast '+(win?close?'close':'win':'loss');box.innerHTML=`<b>${win?close?'CLOSE FIGHT':'LIKELY WIN':'LIKELY LOSS'}</b><span>${win?`${alive}/${total} troops left`:`${b.bosses.filter(x=>x.hp>0).length?'boss survives':'army falls'}`}</span><span class="st">${stars(starsN)}</span>`;if(save.tutorial.ftue&&!save.tutorial.forecast)coach();};}
function powerChip(m:MapData){const need=m.starts.length,have=armyPower(save.levels,save.teams,need),rec=recommendedPower(m),cls=have>=rec?'ok':have>=rec*.85?'mid':'low';return `<div class="g-power ${cls}">${icon.tabBattle} Power <b>${have}</b> / ${rec} recommended</div>`;}
function advice(){const out:string[]=[],have=armyPower(save.levels,save.teams,currentMap.starts.length),rec=recommendedPower(currentMap);const up=Object.keys(U).filter(id=>canUpgrade(save,id));if(up.length)out.push(`▲ Level up <b>${up.map(id=>U[id].name).join(', ')}</b> in Training.`);else if(have<rec)out.push(`Your army is <b>${rec-have}</b> power short. Collect Gold and troop cards to level up.`);if(battle&&battle.enraged)out.push(`<b>${battle.enraged}</b> enemy squad(s) reached the boss. Destroy their camps first, or cross their route.`);const want=(currentMap as any).design?.threeStarBrush;if(currentMap.terrain.length&&want&&want!=='quill'&&!save.brushes[want])out.push(`A <b>${BR[want].name}</b> makes this terrain cheaper.`);if(!out.length)out.push('Try a route that grabs more charms before the boss.');return out;}
function updateBattleHud(){if(!battle)return;let hp=ui.querySelector<HTMLElement>('#g-bosshp'),cur=battle.bosses.reduce((n,b)=>n+Math.max(0,b.hp),0),max=battle.bosses.reduce((n,b)=>n+b.maxHp,0);if(hp)hp.style.width=Math.max(0,cur/max*100)+'%';let rage=ui.querySelector<HTMLElement>('#g-rage');if(rage){rage.style.display=battle.enraged?'':'none';rage.textContent='ENRAGED ×'+battle.enraged;}let time=ui.querySelector('#g-time');if(time)time.textContent=Math.floor(battle.time)+'s · Auto battle';let av=ui.querySelector('#g-avatars');if(av)av.innerHTML=avatars();let camps=ui.querySelector('#g-camps');if(camps)camps.innerHTML=stars(battle.campsDestroyed,currentMap.camps.length);}
function advance(){run().layer++;persist();proceed();}
function stages(){return chapterStages(run().chapter);}
function stageTag(){let list=stages().slice(0,run().layer+1).filter(id=>maps[id]);return `Stage ${list.length}/${stages().filter(id=>maps[id]).length}`;}
function proceed(){offers=[];battle=null;let r=run();if(r.ended){lastResult={clear:false};screen='runend';}else if(r.picks>0){screen='buff';offers=weightedBuffs(r);}else if(r.layer>=stages().length)screen='runend';else{let id=stages()[r.layer];if(id==='shop'){screen='shop';offers=weightedBuffs(r);rerolls=0;}else if(id.startsWith('event:')){screen='event';eventId=id.slice(6);}else{startMap(id);return;}}render();}
function xpAdd(xp:number){let r=run();r.xp+=xp;while(r.level<C.runLevelXp.length&&r.xp>=C.runLevelXp[r.level]){r.xp-=C.runLevelXp[r.level];r.level++;r.picks++;}}
function finish(forced?:boolean){if(!battle||!pool||screen!=='battle')return;drawing=false;grace=0;cursor=null;let win=forced??battle.result==='win',r=run();if(!win){r.ended=true;lastResult={win:false};screen='result';persist();render();return;}
 let last=stages().slice(r.layer+1).every(id=>!maps[id]),type:'battle'|'boss'=last?'boss':'battle';let ink=Math.floor(pool.ink)+battle.lootInk,inkXp=Math.floor(ink*C.inkToXp*(1+runValue(r,'rb_frugal'))),xp=inkXp+C.battleXp[type],coins=Math.floor(C.battleCoins[type]*(1+runValue(r,'rb_golden_touch')))+battle.lootCoins;let camps=battle.campsDestroyed,starCount=Math.min(3,camps+Math.max(0,3-currentMap.camps.length));let opened=currentMap.items.filter((o,i)=>o.type==='chest'&&battle!.collected.has(i)).length;
 let before=save.stars[currentMap.id]||0,gems=Math.max(0,starCount-before)*C.gemsPerStar+(save.cleared[currentMap.id]?0:C.gemsFirstClear);save.cleared[currentMap.id]=true;let gold=C.battleGold[type]+Math.max(0,starCount-before)*10;save.stars[currentMap.id]=Math.max(starCount,before);save.gold+=gold;r.earned+=gold;r.coins+=coins;r.maps.push(currentMap.id);r.goldInk=pool.gold;r.nextHp=1;r.bonus=false;r.picks+=opened;xpAdd(xp);
 if(currentMap.goldZones.length){xpAdd(Math.floor(r.goldInk*C.goldInkToXp));r.goldInk=0;}
 if(last){if(r.picks){gems+=r.picks*C.gemsPerPick;r.picks=0;}let key='chapter'+r.chapter;if(!save.cleared[key]){gems+=C.gemsChapterClear;save.cleared[key]=true;}save.chapter=Math.max(save.chapter,Math.min(chapters.length,r.chapter+1));let clear=C.runClearGold[Math.min(C.runClearGold.length-1,r.chapter-1)];save.gold+=clear;r.earned+=clear;}
 if(currentMap.id==='c1_s1'){save.tutorial.ftue=true;save.tutorial.ftueBattle=true;}save.gems+=gems;lastResult={win,stars:starCount,camps,ink,inkXp,xp,coins,gold,gems,clear:last};r.layer++;screen='result';persist();render();}
function addDebug(){if(!debug)return;let div=document.createElement('div');div.className='debug';div.innerHTML=[['debug-clear','Reset save'],...(screen==='battle'&&!battle?[['debug-path','Draw reference']]:[])].map(([a,t])=>`<button data-action="${a}">${t}</button>`).join('');ui.append(div);}
function newRun(){save.run={chapter,layer:0,teams:save.teams.map(t=>[...t]),brush:save.brush,xp:0,level:0,coins:0,goldInk:0,buffs:{},extras:[0,0,0,0,0,0],nextHp:1,bonus:false,picks:0,maps:[],earned:0};confirm=false;persist();proceed();}
function drawReference(){if(!pool)return;pool.reset();currentMap.referenceSolution.forEach((ref,t)=>ref.forEach(p=>pool!.paths[t]?.add({x:p[0],y:p[1]})));}
ui.addEventListener('click',e=>{let el=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id!;
 switch(a){case 'inspect-active-brush':brushWasPaused=paused;paused=true;brushInspect=true;renderBattle();return;case 'close-active-brush':brushInspect=false;paused=brushWasPaused;renderBattle();return;case 'noop':return;case 'home':screen='home';battle=null;drawing=false;grace=0;detail=null;persist();break;case 'chapter-prev':chapter=Math.max(1,chapter-1);break;case 'chapter-next':chapter=Math.min(chapters.length,chapter+1);break;
 case 'squad':screen='squad';break;case 'slot':pick={team:Number(el.dataset.team),slot:Number(el.dataset.slot)};break;case 'unit':save.teams[pick.team][pick.slot]=id;pick={team:pick.slot===2?(pick.team+1)%2:pick.team,slot:(pick.slot+1)%3};persist();break;
 case 'ask-new':confirm=true;break;case 'cancel':confirm=false;break;case 'new-run':if(chapter>save.chapter||!teamValid(save,save.teams))return;newRun();return;case 'resume':if(run().layer>=stages().length){lastResult={clear:true};}proceed();return;
 case 'brush-prev':case 'brush-next':{let list=Object.keys(save.brushes),i=list.indexOf(run().brush);run().brush=list[(i+(a==='brush-next'?1:list.length-1))%list.length];pool!.fx=fxOf(run().brush);stage.setBrush(run().brush);pool!.reset();persist();renderBattle();return;}
 case 'prepared':preparing=false;renderBattle();return;case 'edit-squad':if(run().maps.length)return;save.run=null;screen='squad';preparing=false;persist();break;case 'team':active=Number(el.dataset.team);updateInk();return;
 case 'reset':pool!.paths[active].reset();grace=0;updateInk();return;case 'undo':pool!.paths[active].undo();grace=0;updateInk();return;case 'start':if(!pool?.valid)return;battleEndAt=0;stepBank=0;battle=new Battle(currentMap,pool,run(),save);grace=0;drawing=false;cursor=null;break;case 'speed':speed=speed===1?2:1;save.speed=speed;persist();break;
 case 'pause':drawing=false;grace=0;paused=true;{let cover=document.createElement('div');cover.innerHTML=battle?popup('PAUSED','blue',`<div class="g-sub">The battle has begun. Retreating counts as a defeat and ends this journey.</div>${btn('unpause','RESUME','big green')}${btn('sound',stage.sound.enabled?'SOUND: ON':'SOUND: OFF','blue')}${btn('retreat','RETREAT','red')}`):popup('PAUSED','blue',`<div class="g-sub">Your journey is saved. Your drawing will be cleared.</div>${btn('unpause','RESUME','big green')}${btn('sound',stage.sound.enabled?'SOUND: ON':'SOUND: OFF','blue')}${btn('battle-home','HOME','blue')}`);ui.append(cover.firstElementChild!);return;}case 'sound':stage.sound.toggle();el.textContent=stage.sound.enabled?'SOUND: ON':'SOUND: OFF';return;case 'unpause':paused=false;break;case 'battle-home':paused=false;screen='home';battle=null;drawing=false;grace=0;persist();break;case 'retreat':paused=false;finish(false);return;
 case 'go-train':case 'go-brush':{if(!lastResult?.win){save.run=null;persist();}screen=a==='go-train'?'upgrade':'brushes';detail=null;brushDetail=null;break;}case 'after-result':if(!lastResult.win){screen='runend';battle=null;}else{proceed();return;}break;case 'end-home':{let r=run();if(lastResult?.clear)chapter=Math.min(chapters.length,r.chapter+1);else chapter=r.chapter;save.run=null;screen='home';persist();break;}
 case 'tut-skip':save.tutorial.ftue=true;save.tutorial.ftueBattle=true;coachHold=false;persist();coach();return;case 'tip-next':tipPage++;coach();return;case 'tip-ok':save.tutorial[id]=true;tipPage=0;if(screen==='battle'&&!id.startsWith('f-')&&id!=='ftueBattle')stageTipDismissed=true;persist();coach();return;case 'pick':save.tutorial.ftue=true;run().buffs[id]=(run().buffs[id]||0)+1;run().picks--;persist();proceed();return;case 'no-picks':run().picks=0;proceed();return;case 'leave-node':advance();return;case 'merc-slot':pick.slot=Number(el.dataset.slot);break;
 case 'event-action':{let r=run();if(eventId==='ev_ink_forge'){if(r.xp<C.forgeXp)return;r.xp-=C.forgeXp;r.goldInk+=C.forgeInk;}if(eventId==='ev_shrine'){r.nextHp=C.shrineHp;let id=weightedBuffs(r,1)[0];if(id)r.buffs[id]=(r.buffs[id]||0)+1;}if(eventId==='ev_mercenary'){if(r.coins<C.mercenaryCost)return;r.coins-=C.mercenaryCost;r.extras[pick.slot]+=C.mercenaryCount;}if(eventId==='ev_mystery_chest'){if(Math.random()<C.mysteryChance)r.picks++;else r.bonus=true;}advance();return;}
 case 'buy':{let r=run();if(!offers.includes(id)||r.coins<R[id].shopPrice)return;r.coins-=R[id].shopPrice;r.buffs[id]=(r.buffs[id]||0)+1;offers=offers.filter(k=>k!==id);persist();toast(R[id].name+'!');break;}case 'buy-gold':if(run().coins<C.goldInkPrice)return;run().coins-=C.goldInkPrice;run().goldInk+=C.goldInkAmount;persist();toast('+'+C.goldInkAmount+' Golden Ink');break;case 'reroll':{let cost=C.shopRerollCost+rerolls*C.shopRerollGrowth;if(run().coins<cost)return;run().coins-=cost;rerolls++;offers=weightedBuffs(run());persist();break;}
 case 'upgrade':screen='upgrade';detail=null;break;case 'detail':detail=id;break;case 'close-detail':detail=null;break;case 'upgrade-unit':if(!upgrade(save,id))return;persist();toast(U[id].name+' Lv '+save.levels[id]+'!');break;
 case 'brushes':screen='brushes';brushDetail=null;brushFocus=id&&BR[id]?id:save.brush;brushSurfaceManual=false;brushTerrain=preferredBrushTerrain(brushFocus);workshopAtTop=true;break;case 'brush-focus':brushFocus=id;brushDetail=null;if(!brushSurfaceManual)brushTerrain=preferredBrushTerrain(id);workshopAtTop=true;break;case 'brush-terrain':brushTerrain=id as TestTerrain;brushSurfaceManual=true;break;case 'brush-try':ui.querySelector('#ink-test')?.scrollIntoView({behavior:'smooth',block:'center'});return;case 'brush-detail':brushDetail=id;break;case 'close-brush':brushDetail=null;break;case 'equip-brush':if(!save.brushes[id])return;save.brush=id;persist();toast(BR[id].name+(save.run&&!save.run.ended&&run().brush!==id?' ready for your next journey':' equipped'));break;
 case 'find-brush':screen='summon';summonTab='brush';pulls=[];brushPulls=[];break;case 'collect-brush':brushFocus=id;brushSurfaceManual=false;brushTerrain=preferredBrushTerrain(id);screen='brushes';brushPulls=[];pulls=[];workshopAtTop=true;break;case 'find-cards':screen='summon';summonTab='troop';detail=null;break;case 'summon':if(!save.tutorial.summon&&save.tutorial.ftue)save.tutorial.summon=true;screen='summon';pulls=[];brushPulls=[];brushDetail=null;break;case 'summon-brush':summonTab='brush';break;case 'summon-troop':summonTab='troop';break;case 'close-pulls':pulls=[];brushPulls=[];break;
 case 'pull-1':case 'pull-10':{let n=a==='pull-1'?1:10,cost=n===1?G.cost:G.tenCost;if(save.gold<cost)return;save.gold-=cost;pulls=Array.from({length:n},()=>pull(save));persist();break;}
 case 'brush-1':case 'brush-10':{let n=a==='brush-1'?1:10,cost=n===1?G.brush.cost:G.brush.tenCost;if(save.gems<cost)return;save.gems-=cost;brushPulls=Array.from({length:n},()=>pullBrush(save));persist();break;}
 case 'debug-path':if(screen==='battle'&&!battle){preparing=false;drawReference();renderBattle();return;}break;case 'debug-win':if(!battle&&pool){drawReference();battle=new Battle(currentMap,pool,run(),save);}finish(true);return;case 'debug-loss':if(!battle&&pool)battle=new Battle(currentMap,pool,run(),save);finish(false);return;case 'debug-gold':save.gold+=500;persist();break;case 'debug-gems':save.gems+=1000;persist();break;case 'debug-xp':if(save.run){xpAdd(100);persist();}break;case 'debug-unlock':save.chapter=chapters.length;Object.keys(U).forEach(k=>save.troops[k]=Math.max(save.troops[k]||0,2));Object.keys(BR).forEach(k=>save.brushes[k]=Math.max(save.brushes[k]||0,1));persist();break;case 'debug-speed':speed=4;break;case 'debug-jump':if(save.run){run().layer=Math.min(run().layer+1,stages().length-1);persist();proceed();return;}break;case 'debug-clear':save=fresh();screen='home';battle=null;pool=null;chapter=1;persist();break;
 }render();});
function pathAt(p:P){if(!pool)return -1;for(let i=0;i<pool.paths.length;i++){let path=pool.paths[i];if(path.valid)continue;if(!path.points.length&&Math.hypot(p.x-path.start.x,p.y-path.start.y)<=C.startSnapRadius)return i;if(path.points.length&&Math.hypot(p.x-path.points.at(-1)!.x,p.y-path.points.at(-1)!.y)<=C.resumeRadius)return i;}return -1;}
canvas.addEventListener('pointerdown',e=>{if(screen!=='battle'||battle||paused||preparing||!pool)return;let p=stage.pick(e);if(!p)return;let i=pathAt(p);if(i<0){let path=pool.paths[active];toast(path.points.length&&!path.valid?'Touch near the tip to continue':'Start from a flag');return;}active=i;drawing=true;grace=0;cursor=p;canvas.setPointerCapture(e.pointerId);pool.paths[i].add(p);updateInk();});
canvas.addEventListener('pointermove',e=>{if(!drawing||!pool||battle||paused)return;let p=stage.pick(e);if(p){cursor=p;let path=pool.paths[active];path.add(p);if(path.valid){drawing=false;cursor=null;let next=pool.paths.findIndex(q=>!q.valid);if(next>=0)active=next;}updateInk();}});
const lift=()=>{cursor=null;if(drawing&&pool&&!pool.paths[active].valid){drawing=false;grace=performance.now()+C.liftGraceSec*1000;updateInk();}};canvas.addEventListener('pointerup',lift);canvas.addEventListener('pointercancel',lift);
let previous=performance.now(),lastHud=0,stepBank=0;function frame(now:number){let dt=Math.min(.06,(now-previous)/1000);previous=now;if(screen==='battle'&&!paused){if(grace&&now>grace){grace=0;pool!.paths[active].reset();updateInk();}if(battle&&!coachHold){stepBank+=dt*speed*C.timeScale;let n=0;while(stepBank>=1/60&&n<40&&!battle.result){battle.step(1/60);stepBank-=1/60;n++;}if(battle.result){if(!battleEndAt){battleEndAt=now;stage.sound.play(battle.result==='win'?'win':'down');}if(now-battleEndAt>1400)finish();}else if(now-lastHud>200){lastHud=now;updateBattleHud();}}}
 if(screen==='home'||screen==='battle')stage.frame(paused?0:dt,screen==='battle'?battle:null,screen==='battle'?pool:null,active,drawing?cursor:null);requestAnimationFrame(frame);}
window.addEventListener('pagehide',persist);render();requestAnimationFrame(frame);

